function timingMark(d?: any): any { const t: any = timing(d); if (!t)
    return ''; const k: any = d.clock, actual: any = ms(k.end || ASOF), span: any = Math.max(k.sla * DAY, actual - ms(k.start)), cut: any = k.sla * DAY / span * 100, endPercent: any = (actual - ms(k.start)) / span * 100; return '<div class="time-result"><span class="timing-mark ' + (t.gap ? 'late-mark' : 'ok-mark') + '">' + (t.gap ? '! ' : '✓ ') + esc(t.label) + '</span><div class="deadline-meter"><i class="meter-normal" style="width:' + Math.min(cut, endPercent) + '%"></i>' + (t.gap ? '<i class="meter-over" style="left:' + cut + '%;width:' + (100 - cut) + '%"></i>' : '') + '<i class="meter-cut" style="left:' + cut + '%" title="应完成截止"></i><i class="meter-end" style="left:' + endPercent + '%" title="' + (t.done ? '实际完成' : '当前查看时点') + '"></i></div><small>截止 ' + shortTime(fmt(t.deadline)) + ' · ' + (t.done ? '实际完成 ' : '仍未完成，截至 ') + shortTime(k.end || ASOF) + '</small></div>'; }
