export function renderTimingDocumentSummary(id:string):string { const b=branchData(makeCase(state.scenario));return b?.docs[id]?docSummary(b,b.docs[id]):'<h3>单据未取得</h3>'; }
export function renderTimingSourceSummaryForCase(c:any,id:string):string {const b=branchData(c)??{docs:Object.fromEntries(c.purchases.map((p:any)=>[p.documentId,findTimingDocument(p.documentId)?.document]))};return b?.docs[id]?docSummary(b,b.docs[id]):'<h3>单据未取得</h3>'}
